import './workspace.css';

const PANEL_KINDS = Object.keys(PANEL_TITLES) as PanelKind[];
const MAX_PANELS_PER_ROW = 4;

function genPanelId(): string {
  return `panel-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function toPanelDocument(config: PanelInstanceConfig, live?: { width: number; height: number }): PanelDocument {
  return {
    id: config.id,
    kind: config.kind,
    symbols: config.symbols,
    linkGroup: config.linkGroup,
    settings: config.settings,
    position: {
      x: 0,
      y: 0,
      width: live?.width && live.width > 0 ? live.width : 400,
      height: live?.height && live.height > 0 ? live.height : 300,
    },
  };
}

// ---------------------------------------------------------------------------
// Imperative <-> React bridge for dockview-core
// ---------------------------------------------------------------------------
// The installed `dockview` package (8.8.3) is a thin, zero-dependency
// re-export of `dockview-core` only - it does NOT ship the `DockviewReact`
// component some older/other dockview distributions provide (verified by
// reading `node_modules/dockview/dist/cjs/index.d.ts`, which is just
// `export * from 'dockview-core'`, and confirming `dockview-core` itself has
// no React bindings). So this file drives dockview-core's imperative
// `createDockview(element, options)` API directly and bridges each panel's
// content/tab into React itself via `react-dom/client`'s `createRoot`. See
// the final report's "Deviations" section for more detail.

interface PanelRenderParams {
  config: PanelInstanceConfig;
}

/** Mutable "latest callbacks" bag so dockview's long-lived factory closures
 * (created once, in the mount effect) always call into the current render's
 * handlers without needing to recreate the DockviewApi every render. */
interface WorkspaceHandlers {
  popOutPanel(panelId: string): void;
  notifyPanelClosed(panelId: string): void;
  updatePanelSymbol(panelId: string, symbol: string): void;
  updatePanelSettings(panelId: string, settings: Record<string, unknown>): void;
}

function PanelUnavailable({ kind }: { kind: string }) {
  return (
    <div className="ws-panel-unavailable">
      <strong>Panel type not available</strong>
      <span>“{kind}” has not been registered in PANEL_COMPONENTS yet.</span>
    </div>
  );
}

function createPanelContentRenderer(handlersRef: React.RefObject<WorkspaceHandlers>): IContentRenderer {
  const element = document.createElement('div');
  element.className = 'ws-panel-content';
  let root: Root | null = null;
  let panelId = '';

  function render(config: PanelInstanceConfig) {
    if (!root) return;
    const Component = PANEL_COMPONENTS[config.kind];
    if (!Component) {
      root.render(<PanelUnavailable kind={config.kind} />);
      return;
    }
    root.render(
      <Component
        config={config}
        onSymbolChange={(symbol) => handlersRef.current?.updatePanelSymbol(panelId, symbol)}
        onSettingsChange={(settings) => handlersRef.current?.updatePanelSettings(panelId, settings)}
      />,
    );
  }

  return {
    element,
    init(parameters: GroupPanelPartInitParameters) {
      panelId = parameters.api.id;
      root = createRoot(element);
      render((parameters.params as PanelRenderParams).config);
    },
    dispose() {
      root?.unmount();
      root = null;
    },
  };
}

function createPanelTabRenderer(handlersRef: React.RefObject<WorkspaceHandlers>): ITabRenderer {
  const element = document.createElement('div');
  element.className = 'ws-tab';
  let root: Root | null = null;
  let panelId = '';
  let closeFn: (() => void) | null = null;

  function render(title: string) {
    if (!root) return;
    root.render(
      <span className="ws-tab__row">
        <span className="ws-tab__title" title={title}>
          {title}
        </span>
        <button
          type="button"
          className="ws-tab__btn"
          title="Pop out to a new window"
          onPointerDown={(e) => e.stopPropagation()}
          onClick={(e) => {
            e.stopPropagation();
            handlersRef.current?.popOutPanel(panelId);
          }}
        >
          ⇗
        </button>
        <button
          type="button"
          className="ws-tab__btn ws-tab__btn--close"
          title="Close panel"
          onPointerDown={(e) => e.stopPropagation()}
          onClick={(e) => {
            e.stopPropagation();
            closeFn?.();
          }}
        >
          ✕
        </button>
      </span>,
    );
  }

  return {
    element,
    init(parameters: TabPartInitParameters) {
      panelId = parameters.api.id;
      closeFn = () => parameters.api.close();
      root = createRoot(element);
      render(parameters.title ?? PANEL_TITLES[(parameters.params as PanelRenderParams)?.config?.kind] ?? 'Panel');
    },
    dispose() {
      root?.unmount();
      root = null;
    },
  };
}

function createEmptyWatermark() {
  const element = document.createElement('div');
  element.className = 'ws-watermark';
  let root: Root | null = null;
  return {
    element,
    init(_parameters: WatermarkRendererInitParameters) {
      root = createRoot(element);
      root.render(
        <div className="ws-watermark__inner">
          <p>No panels yet.</p>
          <p className="ws-watermark__hint">Use “+ Add panel” above to open your first panel.</p>
        </div>,
      );
    },
    dispose() {
      root?.unmount();
      root = null;
    },
  };
}

/** Tracks where the next auto-tiled panel should attach, for a simple grid-ish default layout. */
interface TilingState {
  rowAnchorId: string | undefined;
  lastPanelId: string | undefined;
  countInRow: number;
}

function placementFor(tiling: TilingState): AddPanelOptions['position'] | undefined {
  if (!tiling.lastPanelId) return undefined;
  if (tiling.countInRow >= MAX_PANELS_PER_ROW && tiling.rowAnchorId) {
    return { direction: 'below', referencePanel: tiling.rowAnchorId };
  }
  return { direction: 'right', referencePanel: tiling.lastPanelId };
}

function advanceTiling(tiling: TilingState, newPanelId: string): void {
  if (!tiling.lastPanelId) {
    tiling.rowAnchorId = newPanelId;
    tiling.countInRow = 1;
  } else if (tiling.countInRow >= MAX_PANELS_PER_ROW) {
    tiling.rowAnchorId = newPanelId;
    tiling.countInRow = 1;
  } else {
    tiling.countInRow += 1;
  }
  tiling.lastPanelId = newPanelId;
}

function addDockviewPanel(api: DockviewApi, config: PanelInstanceConfig, tiling: TilingState): void {
  const position = placementFor(tiling);
  const options: AddPanelOptions<PanelRenderParams> = {
    id: config.id,
    title: PANEL_TITLES[config.kind] ?? config.kind,
    component: 'panel',
    tabComponent: 'panelTab',
    params: { config },
    ...(position ? { floating: false, position } : {}),
  };
  api.addPanel(options);
  advanceTiling(tiling, config.id);
}

// ---------------------------------------------------------------------------
// WorkspaceShell
// ---------------------------------------------------------------------------

export interface WorkspaceShellProps {
  /** Panels to seed the main window's grid with (e.g. when the caller already
   * resolved a layout before mounting). Defaults to empty. */
  initialPanels?: PanelInstanceConfig[];
}

export function WorkspaceShell({ initialPanels }: WorkspaceShellProps = {}) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const apiRef = useRef<DockviewApi | null>(null);
  const tilingRef = useRef<TilingState>({ rowAnchorId: undefined, lastPanelId: undefined, countInRow: 0 });
  const handlersRef = useRef<WorkspaceHandlers>(null as unknown as WorkspaceHandlers);
  const panelsStateRef = useRef<PanelInstanceConfig[]>(initialPanels ?? []);

  const storeRef = useRef<LayoutStore>(new LayoutStore(localStorageAdapter));

  const [panels, setPanels] = useState<PanelInstanceConfig[]>(initialPanels ?? []);
  const [newKind, setNewKind] = useState<PanelKind>(PANEL_KINDS[0] ?? 'watchlist');
  const [newSymbol, setNewSymbol] = useState<string>(DEFAULT_WATCHLIST_SYMBOLS[0] ?? 'BTCUSDT');
  const [layoutPanelOpen, setLayoutPanelOpen] = useState(false);
  const [pendingRestore, setPendingRestore] = useState<{ layout: LayoutDocument; blocked: number } | null>(null);

  panelsStateRef.current = panels;

  // "Latest callbacks" assigned every render so the long-lived dockview
  // factory closures (created once below) always see current handlers.
  handlersRef.current = {
    popOutPanel(panelId) {
      const config = panelsStateRef.current.find((p) => p.id === panelId);
      if (!config) return;
      apiRef.current?.getPanel(panelId)?.api.close();
      setPanels((prev) => prev.filter((p) => p.id !== panelId));
      openPopoutWindow(`popout-${panelId}`, [config]);
    },
    notifyPanelClosed(panelId) {
      setPanels((prev) => prev.filter((p) => p.id !== panelId));
    },
    updatePanelSymbol(panelId, symbol) {
      setPanels((prev) =>
        prev.map((p) => (p.id === panelId ? { ...p, symbols: [symbol, ...p.symbols.slice(1)] } : p)),
      );
    },
    updatePanelSettings(panelId, settings) {
      setPanels((prev) => (prev.some((p) => p.id === panelId) ? prev.map((p) => (p.id === panelId ? { ...p, settings } : p)) : prev));
    },
  };

  // Create the dockview instance once on mount.
  useEffect(() => {
    if (!containerRef.current) return;

    const options: DockviewComponentOptions = {
      theme: themeLight,
      className: 'ws-dockview',
      noPanelsOverlay: 'watermark',
      createComponent: () => createPanelContentRenderer(handlersRef),
      createTabComponent: () => createPanelTabRenderer(handlersRef),
      createWatermarkComponent: () => createEmptyWatermark(),
    };

    const api = createDockview(containerRef.current, options);
    apiRef.current = api;

    const removeSub = api.onDidRemovePanel((panel) => {
      handlersRef.current?.notifyPanelClosed(panel.id);
    });

    for (const config of panelsStateRef.current) {
      addDockviewPanel(api, config, tilingRef.current);
    }

    return () => {
      removeSub.dispose();
      api.dispose();
      apiRef.current = null;
    };
    // Intentionally run once: dockview's own imperative API is the source of
    // truth after mount; `panels` state is reconciled into it below instead
    // of recreating the whole component every render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Reconcile `panels` state -> dockview's live panel set (add/remove diff).
  useEffect(() => {
    const api = apiRef.current;
    if (!api) return;

    const nextIds = new Set(panels.map((p) => p.id));
    for (const panel of api.panels) {
      if (!nextIds.has(panel.id)) {
        api.removePanel(panel);
      }
    }

    const remaining = api.panels;
    tilingRef.current = {
      rowAnchorId: remaining[0]?.id,
      lastPanelId: remaining[remaining.length - 1]?.id,
      countInRow: remaining.length > 0 ? ((remaining.length - 1) % MAX_PANELS_PER_ROW) + 1 : 0,
    };

    const currentIds = new Set(api.panels.map((p) => p.id));
    for (const config of panels) {
      if (!currentIds.has(config.id)) {
        addDockviewPanel(api, config, tilingRef.current);
      }
    }
  }, [panels]);

  // Auto-open the default layout's main panels on launch. Pop-out windows in
  // that layout are opened in the same pass, but a page-load has no user
  // gesture, so most browsers will block them; we surface the block count
  // and let the user finish with one explicit click (PRD: "a few clicks to
  // start the restore is acceptable").
  useEffect(() => {
    if (initialPanels && initialPanels.length > 0) return; // caller already seeded panels explicitly.
    const defaultLayout = storeRef.current.getDefault();
    if (!defaultLayout) return;
    applyRestoredLayout(defaultLayout);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function applyRestoredLayout(layout: LayoutDocument) {
    const result = restoreLayout(layout);
    setPanels(result.mainPanels);
    setPendingRestore(result.blockedWindows > 0 ? { layout, blocked: result.blockedWindows } : null);
    setLayoutPanelOpen(false);
  }

  function handleFinishPopouts() {
    if (!pendingRestore) return;
    const { opened, blocked } = openPopoutWindowsForLayout(pendingRestore.layout);
    void opened;
    setPendingRestore(blocked > 0 ? { layout: pendingRestore.layout, blocked } : null);
  }

  function handleAddPanel() {
    const kind = newKind;
    const trimmedSymbol = newSymbol.trim().toUpperCase();
    const symbols = kind === 'watchlist' ? [...DEFAULT_WATCHLIST_SYMBOLS] : [trimmedSymbol || DEFAULT_WATCHLIST_SYMBOLS[0]];
    const config: PanelInstanceConfig = {
      id: genPanelId(),
      kind,
      symbols,
      linkGroup: null,
      settings: {},
    };
    setPanels((prev) => [...prev, config]);
  }

  function buildCurrentLayoutInput(): NewLayoutInput {
    const api = apiRef.current;
    const panelDocs = panels.map((config) => {
      const live = api?.getPanel(config.id);
      return toPanelDocument(
        config,
        live ? { width: live.api.width, height: live.api.height } : undefined,
      );
    });
    return {
      name: 'Untitled layout',
      windows: [{ id: 'main', role: 'main', panelIds: panelDocs.map((p) => p.id) }],
      panels: panelDocs,
    };
  }

  const kindOptions = useMemo(
    () => PANEL_KINDS.map((kind) => ({ kind, title: PANEL_TITLES[kind] })),
    [],
  );

  return (
    <LinkGroupProvider>
      <div className="ws-root">
        <header className="ws-toolbar">
          <div className="ws-toolbar__group">
            <select
              className="ws-toolbar__select"
              value={newKind}
              onChange={(e: ChangeEvent<HTMLSelectElement>) => setNewKind(e.target.value as PanelKind)}
              aria-label="Panel type"
            >
              {kindOptions.map(({ kind, title }) => (
                <option key={kind} value={kind}>
                  {title}
                  {!PANEL_COMPONENTS[kind] ? ' (unavailable)' : ''}
                </option>
              ))}
            </select>
            <input
              className="ws-toolbar__input"
              value={newSymbol}
              onChange={(e: ChangeEvent<HTMLInputElement>) => setNewSymbol(e.target.value)}
              placeholder="Symbol, e.g. BTCUSDT"
              aria-label="Initial symbol"
              disabled={newKind === 'watchlist'}
            />
            <button type="button" className="ws-toolbar__btn ws-toolbar__btn--primary" onClick={handleAddPanel}>
              + Add panel
            </button>
          </div>

          <div className="ws-toolbar__spacer" />

          {pendingRestore && (
            <button type="button" className="ws-toolbar__banner" onClick={handleFinishPopouts}>
              {pendingRestore.blocked} pop-out window{pendingRestore.blocked === 1 ? '' : 's'} blocked by the
              browser — click to open
            </button>
          )}

          <button type="button" className="ws-toolbar__btn" onClick={() => setLayoutPanelOpen((v) => !v)}>
            Layouts
          </button>
        </header>

        <div className="ws-body">
          <div ref={containerRef} className="ws-dockview-container" />
          {layoutPanelOpen && (
            <LayoutPanel
              store={storeRef.current}
              getCurrentLayoutInput={buildCurrentLayoutInput}
              onRestoreLayout={applyRestoredLayout}
              onClose={() => setLayoutPanelOpen(false)}
            />
          )}
        </div>
      </div>
    </LinkGroupProvider>
  );
}

import React, { useRef, useState } from 'react';
import type { LayoutStore, NewLayoutInput } from '../core/layout/LayoutStore';
import type { LayoutDocument } from '../core/layout/schema';
import './workspace.css';

export interface LayoutPanelProps {
  store: LayoutStore;
  /** Captures the live workspace (main window panels/positions) as save-ready input; `name` is a placeholder the save flow overwrites. */
  getCurrentLayoutInput: () => NewLayoutInput;
  /** Applies a chosen layout back into the workspace (and opens its pop-out windows). */
  onRestoreLayout: (layout: LayoutDocument) => void;
  onClose?: () => void;
}

function slugify(name: string): string {
  const slug = name
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return slug || 'layout';
}

function formatUpdatedAt(ms: number): string {
  try {
    return new Date(ms).toLocaleString();
  } catch {
    return String(ms);
  }
}

export function LayoutPanel({ store, getCurrentLayoutInput, onRestoreLayout, onClose }: LayoutPanelProps) {
  const [layouts, setLayouts] = useState<LayoutDocument[]>(() => store.list());
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  function refresh() {
    setLayouts(store.list());
  }

  function handleSaveAsNew() {
    const name = window.prompt('Name this layout:', '');
    if (!name || !name.trim()) return;
    setError(null);
    const input = getCurrentLayoutInput();
    try {
      store.save({ ...input, name: name.trim() });
      refresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to save layout.');
    }
  }

  function handleLoad(doc: LayoutDocument) {
    const fresh = store.get(doc.id);
    if (!fresh) {
      setError('That layout no longer exists.');
      refresh();
      return;
    }
    onRestoreLayout(fresh);
  }

  function handleRename(doc: LayoutDocument) {
    const name = window.prompt('Rename layout:', doc.name);
    if (!name || !name.trim() || name.trim() === doc.name) return;
    setError(null);
    try {
      store.rename(doc.id, name.trim());
      refresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to rename layout.');
    }
  }

  function handleDelete(doc: LayoutDocument) {
    if (!window.confirm(`Delete layout “${doc.name}”? This cannot be undone.`)) return;
    setError(null);
    try {
      store.delete(doc.id);
      refresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to delete layout.');
    }
  }

  function handleSetDefault(doc: LayoutDocument) {
    setError(null);
    try {
      store.setDefault(doc.id);
      refresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to set default layout.');
    }
  }

  function handleExport(doc: LayoutDocument) {
    setError(null);
    try {
      const json = store.exportJson(doc.id);
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${slugify(doc.name)}.layout.json`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to export layout.');
    }
  }

  function handleImportFile(file: File) {
    setError(null);
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const text = typeof reader.result === 'string' ? reader.result : '';
        store.importJson(text);
        refresh();
      } catch (e) {
        setError(
          e instanceof Error
            ? `Import failed: ${e.message}`
            : 'Import failed: the file is not a valid layout export.',
        );
      }
    };
    reader.onerror = () => setError('Could not read the selected file.');
    reader.readAsText(file);
  }

  return (
    <aside className="layout-panel" role="complementary" aria-label="Saved layouts">
      <header className="layout-panel__header">
        <h2 className="layout-panel__title">Layouts</h2>
        {onClose && (
          <button type="button" className="layout-panel__close" onClick={onClose} aria-label="Close layouts panel">
            ✕
          </button>
        )}
      </header>

      <div className="layout-panel__actions">
        <button type="button" className="ws-toolbar__btn ws-toolbar__btn--primary" onClick={handleSaveAsNew}>
          Save current as new layout
        </button>
        <button type="button" className="ws-toolbar__btn" onClick={() => fileInputRef.current?.click()}>
          Import…
        </button>
        <input
          ref={fileInputRef}
          type="file"
          accept="application/json,.json"
          className="layout-panel__file-input"
          onChange={(e) => {
            const file = e.target.files?.[0];
            if (file) handleImportFile(file);
            e.target.value = '';
          }}
        />
      </div>

      {error && (
        <p className="layout-panel__error" role="alert">
          {error}
        </p>
      )}

      <ul className="layout-panel__list">
        {layouts.length === 0 && <li className="layout-panel__empty">No saved layouts yet.</li>}
        {layouts.map((doc) => (
          <li key={doc.id} className="layout-panel__item">
            <div className="layout-panel__item-main">
              <span className="layout-panel__name">{doc.name}</span>
              {doc.isDefault && <span className="layout-panel__badge">Default</span>}
              <span className="layout-panel__meta">Updated {formatUpdatedAt(doc.updatedAt)}</span>
            </div>
            <div className="layout-panel__item-actions">
              <button type="button" onClick={() => handleLoad(doc)}>
                Load
              </button>
              <button type="button" onClick={() => handleRename(doc)}>
                Rename
              </button>
              <button type="button" onClick={() => handleSetDefault(doc)} disabled={doc.isDefault}>
                Set default
              </button>
              <button type="button" onClick={() => handleExport(doc)}>
                Export
              </button>
              <button type="button" className="layout-panel__btn--danger" onClick={() => handleDelete(doc)}>
                Delete
              </button>
            </div>
          </li>
        ))}
      </ul>
    </aside>
  );
}

/*
 * Workspace UI styles. Light theme only, by design (PRD constraint) - reuses
 * the CSS custom properties defined in src/styles/global.css (--color-*,
 * --font-*) so this stays visually consistent with the rest of the app
 * without duplicating palette decisions. Dense, high-information layout
 * suited to a professional trading terminal: small type, tight spacing,
 * subtle borders instead of heavy chrome.
 */

.ws-root {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  background: var(--color-bg, #f5f6f8);
  color: var(--color-text, #1a1d23);
  font-family: var(--font-sans, sans-serif);
}

/* ---- Toolbar -------------------------------------------------------- */

.ws-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  background: var(--color-surface, #fff);
  border-bottom: 1px solid var(--color-border, #d9dce1);
  flex: 0 0 auto;
}

.ws-toolbar__group {
  display: flex;
  align-items: center;
  gap: 6px;
}

.ws-toolbar__spacer {
  flex: 1 1 auto;
}

.ws-toolbar__select,
.ws-toolbar__input {
  font-size: 12px;
  padding: 4px 6px;
  border: 1px solid var(--color-border, #d9dce1);
  border-radius: 3px;
  background: var(--color-surface, #fff);
  color: var(--color-text, #1a1d23);
  height: 26px;
}

.ws-toolbar__input {
  width: 140px;
}

.ws-toolbar__input:disabled {
  background: var(--color-surface-alt, #f0f1f4);
  color: var(--color-text-muted, #6b7280);
}

.ws-toolbar__btn {
  font-size: 12px;
  padding: 4px 10px;
  height: 26px;
  border: 1px solid var(--color-border, #d9dce1);
  border-radius: 3px;
  background: var(--color-surface, #fff);
  color: var(--color-text, #1a1d23);
  cursor: pointer;
}

.ws-toolbar__btn:hover {
  background: var(--color-surface-alt, #f0f1f4);
}

.ws-toolbar__btn--primary {
  background: var(--color-accent, #1458c7);
  border-color: var(--color-accent, #1458c7);
  color: #fff;
}

.ws-toolbar__btn--primary:hover {
  filter: brightness(1.08);
}

.ws-toolbar__banner {
  font-size: 12px;
  padding: 4px 10px;
  height: 26px;
  border: 1px solid var(--color-warn, #b7791f);
  border-radius: 3px;
  background: var(--color-warn-bg, #fdf3e0);
  color: var(--color-warn, #b7791f);
  cursor: pointer;
}

/* ---- Body / dockview container --------------------------------------- */

.ws-body {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
}

.ws-dockview-container {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
}

/* Light-theme accent tweaks layered over dockview's built-in `themeLight`,
   kept to the project's own border/surface palette. */
.ws-dockview.dockview-theme-light {
  --dv-separator-border: var(--color-border, #d9dce1);
  --dv-tabs-and-actions-container-background-color: var(--color-surface-alt, #f0f1f4);
  --dv-group-view-background-color: var(--color-surface, #fff);
  --dv-activegroup-visiblepanel-tab-background-color: var(--color-surface, #fff);
  --dv-inactivegroup-visiblepanel-tab-background-color: var(--color-surface-alt, #f0f1f4);
  --dv-tabs-and-actions-container-font-size: 12px;
  --dv-tabs-and-actions-container-height: 28px;
}

.ws-panel-content {
  width: 100%;
  height: 100%;
  overflow: auto;
  font-family: var(--font-mono, monospace);
  font-size: 12px;
}

.ws-panel-unavailable {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  height: 100%;
  padding: 16px;
  text-align: center;
  color: var(--color-text-muted, #6b7280);
  font-size: 12px;
}

/* ---- Custom tab (title + pop-out + close) ---------------------------- */

.ws-tab {
  height: 100%;
  display: flex;
  align-items: center;
}

.ws-tab__row {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0 6px;
  max-width: 220px;
}

.ws-tab__title {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
}

.ws-tab__btn {
  flex: 0 0 auto;
  border: none;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font-size: 11px;
  line-height: 1;
  padding: 2px 3px;
  border-radius: 2px;
  opacity: 0.65;
}

.ws-tab__btn:hover {
  opacity: 1;
  background: var(--color-surface-alt, #f0f1f4);
}

.ws-tab__btn--close:hover {
  color: var(--color-sell, #c21e34);
}

/* ---- Empty-grid watermark --------------------------------------------- */

.ws-watermark {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.ws-watermark__inner {
  text-align: center;
  color: var(--color-text-muted, #6b7280);
  font-size: 12px;
}

.ws-watermark__hint {
  font-size: 11px;
}

/* ---- Layouts side panel ------------------------------------------------ */

.layout-panel {
  flex: 0 0 320px;
  display: flex;
  flex-direction: column;
  border-left: 1px solid var(--color-border, #d9dce1);
  background: var(--color-surface, #fff);
  overflow-y: auto;
}

.layout-panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px;
  border-bottom: 1px solid var(--color-border, #d9dce1);
}

.layout-panel__title {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
}

.layout-panel__close {
  border: none;
  background: transparent;
  cursor: pointer;
  font-size: 13px;
  color: var(--color-text-muted, #6b7280);
}

.layout-panel__actions {
  display: flex;
  gap: 6px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--color-border, #d9dce1);
  flex-wrap: wrap;
}

.layout-panel__file-input {
  display: none;
}

.layout-panel__error {
  margin: 8px 10px 0;
  padding: 6px 8px;
  border-radius: 3px;
  background: var(--color-sell-bg, #fbe9eb);
  color: var(--color-sell, #c21e34);
  font-size: 12px;
}

.layout-panel__list {
  list-style: none;
  margin: 0;
  padding: 0;
  flex: 1 1 auto;
}

.layout-panel__empty {
  padding: 16px 10px;
  color: var(--color-text-muted, #6b7280);
  font-size: 12px;
  text-align: center;
}

.layout-panel__item {
  padding: 8px 10px;
  border-bottom: 1px solid var(--color-border, #d9dce1);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.layout-panel__item-main {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.layout-panel__name {
  font-size: 13px;
  font-weight: 600;
}

.layout-panel__badge {
  align-self: flex-start;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  padding: 1px 6px;
  border-radius: 10px;
  background: var(--color-buy-bg, #e6f6ec);
  color: var(--color-buy, #0a7d3c);
}

.layout-panel__meta {
  font-size: 11px;
  color: var(--color-text-muted, #6b7280);
}

.layout-panel__item-actions {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}

.layout-panel__item-actions button {
  font-size: 11px;
  padding: 3px 7px;
  border: 1px solid var(--color-border, #d9dce1);
  border-radius: 3px;
  background: var(--color-surface, #fff);
  color: var(--color-text, #1a1d23);
  cursor: pointer;
}

.layout-panel__item-actions button:hover {
  background: var(--color-surface-alt, #f0f1f4);
}

.layout-panel__item-actions button:disabled {
  opacity: 0.5;
  cursor: default;
}

.layout-panel__btn--danger {
  color: var(--color-sell, #c21e34) !important;
  border-color: var(--color-sell, #c21e34) !important;
}
